begin
  -- Serialize this catalog compiler only; do not block unrelated application writes.
  perform pg_advisory_xact_lock(1742026104, 401);
  v_baseline := (select jsonb_build_object('recipes',(select md5(coalesce(string_agg(md5(row::text),'' order by id),'')) from (select r.id,to_jsonb(r) as row from public.recipes r where r.slug is null or r.slug not in ('kalita-usa-pour-over-20g-320g')) untouched),'roasters',(select md5(coalesce(string_agg(md5(row::text),'' order by id),'')) from (select r.id,to_jsonb(r) as row from public.roasters r where r.slug is null or r.slug not in ('tahnah-roastery','hazan-roastery')) untouched),'beans',(select md5(coalesce(string_agg(md5(row::text),'' order by id),'')) from (select r.id,to_jsonb(r) as row from public.beans r) untouched),'recipe_steps',(select md5(coalesce(string_agg(md5(row::text),'' order by id),'')) from (select s.id,to_jsonb(s) as row from public.recipe_steps s join public.recipes r on r.id=s.recipe_id where r.slug is null or r.slug not in ('kalita-usa-pour-over-20g-320g')) untouched),'recipe_pours',(select md5(coalesce(string_agg(md5(row::text),'' order by id),'')) from (select s.id,to_jsonb(s) as row from public.recipe_pours s join public.recipes r on r.id=s.recipe_id where r.slug is null or r.slug not in ('kalita-usa-pour-over-20g-320g')) untouched),'recipe_sources',(select md5(coalesce(string_agg(md5(row::text),'' order by id),'')) from (select s.id,to_jsonb(s) as row from public.recipe_sources s join public.recipes r on r.id=s.recipe_id where r.slug is null or r.slug not in ('kalita-usa-pour-over-20g-320g')) untouched))::text);
  select p.id into strict v_curator from public.profiles p where p.username = 'beanmora_official';

  if exists (select 1 from jsonb_array_elements(v_catalog->'recipes') x where not exists (select 1 from public.brew_methods bm where bm.code=x.value->>'brew_method')) then
